<template>
  <div class="flex-interval" style="height: 100%">
    <div class="tree">
     <DeviceTree @node-click="handleNodeClick" />
    </div>
    <div class="p-15" style="width: 65vw; overflow: auto">
      <el-tabs v-model="activeName" @tab-click="handleClick">
        <el-tab-pane label="报警记录" name="1"> </el-tab-pane>
        <el-tab-pane label="数据记录" name="2"> </el-tab-pane>
        <component
          :key="componentKey"
          :is="componentsListName"
          :chooseItem="chooseItem"
          ref="recordsRef"
          :activeName="activeName"
          :recordsList="recordsList"
          :AiValueList="AiValueList"
        ></component>
        <pagination
          class="float-right mt-10 mb-10"
          v-show="aiTotal > 0"
          :total="aiTotal"
          :page.sync="attributeParams.page"
          :limit.sync="attributeParams.size"
          @pagination="activeName == '1' ? getDataList() : getDataAiValueList()"
          layout="total, prev, pager, next"
          small
        />
      </el-tabs>
    </div>
  </div>
</template>

<script>
import onvif from "./components/records/onvif.vue";
import Modbus from "./components/records/Modbus.vue";
import GB28181 from "./components/records/GB28181.vue";
import DeviceTree from "@/components/deviceTree.vue";
export default {
  components: {
    onvif,
    Modbus,
    GB28181,
    DeviceTree
  },
  data() {
    return {

      recordsList: [],
      chooseItem: {},
      attributeParams: {
        page: 1,
        size: 10,
      },
      activeName: "1",
      expandedKeys: [],
      checkedKeys: [],
      AiValueList: [],
      aiTotal: 0,
      componentKey: 0,
      componentsListName: "onvif",
      source_type: new Map([
        [1, "Modbus"],
        [2, "onvif"],
        [3, "onvif"],
        [4, "Modbus"],
      ]),
    };
  },

  mounted() {
    this.setStyle();
  },
  filters: {
    toFixed(value) {
      return Number(value).toFixed(2);
    },
  },
  methods: {
    parsedData(row) {
      try {
        return JSON.parse(row.ai_value) || [];
      } catch (e) {
        console.error("解析ai_value失败:", e);
        return [];
      }
    },
    shouldShowMore(row) {
      return this.parsedData(row).length > 4;
    },
    getDataAiValueList() {
      this.$api
        .get(`/collect/getDataRecordList`, {
          params: this.attributeParams,
        })
        .then((res) => {
          if (res.data.data) {
            this.AiValueList = res.data.data;
            this.aiTotal = res.data.total;
          } else {
            this.AiValueList = [];
          }
        });
    },
    getDataList() {
      this.$api
        .get(`/ai/getDataAiRecordList`, {
          params: this.attributeParams,
        })
        .then((res) => {
          if (res.data.data) {
            this.recordsList = res.data.data;
            this.aiTotal = res.data.total;
          } else {
            this.aiTotal = 0;
            this.recordsList = [];
          }
        });
    },


    handleClick(e) {
      this.recordsList = []; // 清空报警记录数据
      this.AiValueList = []; // 清空数据记录数据
      this.aiTotal = 0;
      this.attributeParams.page = 1;
      this.componentKey = `${this.componentsListName}_${Date.now()}`;
      if (e.index == "0") {
        this.getDataList();
      } else {
        this.getDataAiValueList();
      }
    },
  
    setStyle() {
      const elMain = document.querySelector(".el-main");
      if (elMain) {
        elMain.style.padding = "0px";
        elMain.style.overflow = "hidden";
      }
    },
    handleNodeClick(data, node) {
      this.recordsList = []; // 清空报警记录数据
      this.AiValueList = []; // 清空数据记录数据
      this.aiTotal = 0;
      this.activeName = "1";
      this.chooseItem = data;
      this.attributeParams = {
        page: 1,
        size: 10,
      };
      if (node.level == 1) {
        this.attributeParams.source_id = data.id;
      } else {
        this.attributeParams.pro_id = data.id;
      }
      this.componentsListName = this.source_type.get(
        this.chooseItem.driver_protocol
      );
      this.componentKey = `${this.componentsListName}_${Date.now()}`;
      this.getDataList();
    },
    getAttributeList() {},
  },
  beforeDestroy() {
    const elMain = document.querySelector(".el-main");
    if (elMain) {
      elMain.style.padding = "20px";
      elMain.style.overflow = "auto";
    }
  },
};
</script>

<style lang="scss" scoped>
.tree {
  width: 12vw;
  border-right: 5px solid #f4f4f4;
  height: 100%;
  padding: 15px;
}
</style>
